import android.content.*;import java.io.*;import java.nio.charset.*;import org.json.*;
public class BannerPreferenceTest {
 static void check(boolean v,String m){if(!v)throw new AssertionError(m);}static String enc(String s){return android.util.Base64.encodeToString(s.getBytes(StandardCharsets.UTF_8),2);}static JSONObject dec(String s)throws Exception{return new JSONObject(new String(android.util.Base64.decode(s,0),StandardCharsets.UTF_8));}
 public static void main(String[] args)throws Exception{
 File root=new File(args[0]),dir=new File(root,"shared_prefs");dir.mkdirs();File marker=new File(root,".husk-hide-cricfy-banner");marker.delete();HuskSharedPreferences p=new HuskSharedPreferences(new File(dir,"rtstv.xml"));
 String json="{\"start\":{\"enabled\":true},\"unity\":{\"enabled\":true},\"sponsor\":{\"enable\":true,\"image\":\"original-image\"},\"sponsors\":[{\"enabled\":true},{\"enabled\":false},{\"enabled\":true},{\"enabled\":true},{\"enabled\":true,\"link\":\"original-link\"}]}";String original=enc(json);p.edit().putString("ass",original).putLong("last events",123L).commit();check(p.getString("ass",null).equals(original),"disabled-by-default exact pass-through");marker.createNewFile();JSONObject value=dec(p.getString("ass",null));check(!value.getJSONObject("sponsor").getBoolean("enable"),"fallback banner disabled");check(!value.getJSONArray("sponsors").getJSONObject(4).getBoolean("enabled"),"web banner disabled");check(value.getJSONObject("start").getBoolean("enabled")&&value.getJSONObject("unity").getBoolean("enabled"),"other ad formats preserved");check(value.getJSONArray("sponsors").getJSONObject(3).getBoolean("enabled"),"other placements preserved");check(value.getJSONObject("sponsor").getString("image").equals("original-image"),"other fields retained");check(p.getAll().get("ass").equals(original),"stored original unmodified");
 p.edit().putString("ass",original).commit();check(!dec(p.getString("ass",null)).getJSONObject("sponsor").getBoolean("enable"),"server refresh cannot re-enable banner while opted in");HuskSharedPreferences reopened=new HuskSharedPreferences(new File(dir,"rtstv.xml"));check(!dec(reopened.getString("ass",null)).getJSONArray("sponsors").getJSONObject(4).getBoolean("enabled"),"override survives reopen");check(reopened.getLong("last events",0)==123L,"space-in-key relaunch fix preserved");
 p.edit().putString("other",original).commit();check(p.getString("other",null).equals(original),"other preference keys unaffected");HuskSharedPreferences unrelated=new HuskSharedPreferences(new File(dir,"other.xml"));unrelated.edit().putString("ass",original).commit();check(unrelated.getString("ass",null).equals(original),"other preference files unaffected");
 for(String bad:new String[]{"not-base64",enc("invalid JSON"),enc("{}"),enc("{\"sponsors\":[]}")}){p.edit().putString("ass",bad).commit();check(p.getString("ass",null).equals(bad),"unknown/malformed format preserved");}
 p.edit().putString("ass",original).commit();marker.delete();check(p.getString("ass",null).equals(original),"removing marker restores behavior");System.out.println("PASS: opt-in banner/fallback suppression, refresh/reopen persistence, other settings unchanged, malformed pass-through, marker removal restores defaults");
 }
}